/// A neutral wallet glyph used when neither the wallet's own icon nor a
/// bundled fallback logo is available.
WalletIcon genericWalletLogo() => WalletIcon(_genericLogoUri);

/// Returns a bundled logo for a popular wallet, or null when [walletName] is
/// not in the bundled set. Matching is case-insensitive and ignores a trailing
/// "Wallet" suffix, so "Trust Wallet" resolves the "Trust" logo.
WalletIcon? walletLogoFallback(String walletName) {
  final key = walletName.trim().toLowerCase();
  final uri =
      _fallbackLogoUris[key] ??
      (key.endsWith(' wallet')
          ? _fallbackLogoUris[key.substring(0, key.length - ' wallet'.length)]
          : null);
  final resolved = uri ?? _fallbackLogoUris['$key wallet'];
  if (resolved == null) return null;
  return WalletIcon(resolved);
}
